// Owner question set 2 (V1.15), part B: Stream API product coding exercise, multithreading and concurrency.
import { kp, Q } from './kp.js';

const CX = 'Coding Exercises', CC = 'Concurrency';
const src = { source: 'owner-set2' };

export const V115_B = [
  // ---------------------------------------------------------------- 4. Stream API product coding exercise
  Q('nq-053', CX, 'MS', 'scenario', 'Given a list of product objects, how would you implement multiple filtering, transformation, sorting, and aggregation operations using streams?',
    [kp('Model Product with name, category, price, stock (record)', 'record', 'product', 'category', 'price', 'stock'), kp('filter for conditions, map for transformations', 'filter', 'map'), kp('sorted with Comparator.comparing', 'sorted', 'comparator'), kp('Collectors.groupingBy / summingDouble for aggregation', 'groupingby', 'summingdouble', 'collectors'), kp('Separate pipelines per question; keep source unchanged', 'separate', 'pipeline*', 'unchanged', 'immutable')],
    'I would start with a small immutable model, record Product(String name, String category, double price, int stock), and a sample list. Then I would write one clear pipeline per requirement rather than one huge chain. Filtering uses filter with a predicate, such as stock below 10. Transformations use map, for example creating discounted copies or upper case names with a method reference. Sorting uses sorted(Comparator.comparing(Product::name)). Aggregation uses collectors: groupingBy(Product::category) to group, with summingDouble(Product::price) for totals per category, and max with comparingDouble for the most expensive product. I would talk through each step, keep the source list unchanged, and test with a few products.',
    'How would you test these pipelines?', src),
  Q('nq-054', CX, 'E', 'scenario', 'How would you filter products whose stock count is below 10?',
    [kp('stream().filter(p -> p.getStock() < 10)', 'filter', 'stock', '< 10', 'less than 10'), kp('Collect with toList() / Collectors.toList()', 'tolist', 'collect'), kp('Predicate could be named/reused', 'predicate', 'reuse')],
    'List<Product> lowStock = products.stream().filter(p -> p.getStock() < 10).toList(); filter keeps only elements for which the predicate returns true, and toList, available since Java 16, collects them into an unmodifiable list; on Java 8 use collect(Collectors.toList()). If the rule is reused, name it: Predicate<Product> lowStock = p -> p.getStock() < 10; and combine it with others using and or negate. The original list is not modified.',
    'How would you also count them without collecting a list?', src),
  Q('nq-055', CX, 'M', 'scenario', 'How would you apply a 15% discount to products satisfying a specified condition?',
    [kp('Filter or use a conditional in map', 'filter', 'condition', 'ternary', 'if'), kp('Multiply price by 0.85', '0.85', '15', 'discount'), kp('Create new product objects (immutable) or update with forEach', 'new product', 'record', 'foreach', 'setprice'), kp('Use BigDecimal for money in real code', 'bigdecimal', 'money', 'round*')],
    'If I want only the discounted products: products.stream().filter(condition).map(p -> new Product(p.name(), p.category(), p.price() * 0.85, p.stock())).toList(). If I want the full list with discounts applied only where the condition holds, I use a conditional inside map: .map(p -> condition.test(p) ? p.withPrice(p.price() * 0.85) : p). That keeps objects immutable. If the requirement is to update the existing mutable objects in place, I would instead filter and then forEach(p -> p.setPrice(p.getPrice() * 0.85)). In production code I would use BigDecimal and proper rounding for money, since double gives rounding errors.',
    'Why is double a poor choice for prices?', src),
  Q('nq-056', CX, 'M', 'concept', 'Why might you use forEach() instead of map() to apply a discount?',
    [kp('forEach is for side effects: updating existing objects in place', 'side effect*', 'in place', 'existing object*', 'mutat*'), kp('map is meant to return transformed values, not to mutate', 'map', 'return', 'transform*'), kp('Mutating inside map plus collect is misleading', 'misleading', 'peek', 'collect'), kp('Prefer map with new objects when immutability matters', 'immutab*', 'new object*')],
    'map is meant to produce a new value for each element; its result flows into the next stage and the collector. If the goal is to change the existing Product objects, for example call setPrice on entities that will then be saved, that is a side effect, and forEach is the operation designed for side effects: products.stream().filter(cond).forEach(p -> p.setPrice(p.getPrice() * 0.85)). Doing the mutation inside map and returning the same object works, but it is misleading, it breaks the expectation that map is pure, and it may not even run without a terminal operation. If immutability matters, I prefer map creating new objects.',
    'Would List.forEach or replaceAll be simpler here?', src),
  Q('nq-057', CX, 'M', 'scenario', 'How would you create new product objects rather than modifying existing objects?',
    [kp('map to a new instance via constructor or copy method', 'new product', 'constructor', 'copy'), kp('Records or immutable classes with wither methods', 'record*', 'with*', 'immutable'), kp('Builder/toBuilder pattern (Lombok)', 'builder', 'tobuilder', 'lombok'), kp('Originals unchanged; safe to share and for parallel streams', 'original*', 'unchanged', 'thread safe', 'parallel')],
    'In the map step I return a new instance instead of calling setters: .map(p -> new Product(p.getName(), p.getCategory(), p.getPrice() * 0.85, p.getStock())). With a record I can add a wither method, record Product(...) { Product withPrice(double newPrice) { return new Product(name, category, newPrice, stock); } }, and write .map(p -> p.withPrice(p.price() * 0.85)). With Lombok, @Builder(toBuilder = true) gives p.toBuilder().price(newPrice).build(). The original list and objects stay unchanged, which makes the code easier to reason about, safe to share between threads and correct with parallel streams.',
    'What are the costs of creating new objects for every change?', src),
  Q('nq-058', CX, 'E', 'scenario', 'How would you update existing product objects using forEach()?',
    [kp('Iterate and call setters inside forEach', 'foreach', 'setter*', 'setprice'), kp('Optionally filter first', 'filter'), kp('Collection.forEach or stream().forEach', 'collection.foreach', 'list.foreach', 'stream'), kp('Objects must be mutable; not thread-safe in parallel', 'mutable', 'thread', 'parallel')],
    'If Product is a mutable class with setters: products.stream().filter(p -> p.getCategory().equals("Electronics")).forEach(p -> p.setPrice(p.getPrice() * 0.85)); or without filtering, products.forEach(p -> p.setPrice(p.getPrice() * 0.85)), using Iterable.forEach directly. The list keeps the same objects, now with new prices, so anyone holding references sees the change. This only works with mutable objects, should not be done in a parallel stream over shared objects, and must not add or remove elements of the list during iteration.',
    'What happens if you remove elements from the list inside forEach?', src),
  Q('nq-059', CX, 'E', 'scenario', 'How would you collect transformed products into a new list?',
    [kp('map then collect(Collectors.toList()) or toList()', 'collect', 'tolist', 'collectors.tolist'), kp('toList() returns an unmodifiable list', 'unmodifiable', 'immutable'), kp('Collectors.toCollection(ArrayList::new) for a mutable list', 'tocollection', 'arraylist::new', 'mutable')],
    'List<Product> discounted = products.stream().map(p -> p.withPrice(p.price() * 0.85)).collect(Collectors.toList()); Since Java 16 you can write .toList(), which returns an unmodifiable list, so later add calls throw UnsupportedOperationException. Collectors.toList makes no guarantee about mutability, though in practice it is an ArrayList. If the caller needs a specific mutable type, use Collectors.toCollection(ArrayList::new) or LinkedList::new. Collectors.toUnmodifiableList is the explicit immutable version on Java 10 and later.',
    'What is the difference between toList() and Collectors.toList()?', src),
  Q('nq-060', CX, 'E', 'scenario', 'How would you sort products by name using Comparator?',
    [kp('sorted(Comparator.comparing(Product::getName))', 'comparator.comparing', 'sorted', 'getname'), kp('reversed() for descending', 'reversed'), kp('thenComparing for ties; nullsFirst/caseInsensitive', 'thencomparing', 'nullsfirst', 'case_insensitive', 'ignorecase'), kp('list.sort for in-place sort', 'list.sort', 'in place')],
    'I would pass a comparator built from the name getter: products.stream().sorted(Comparator.comparing(Product::getName)).toList() sorts by name ascending using natural String order, and returns a new list while the original stays as it is. For descending, add .reversed(); for case-insensitive, Comparator.comparing(Product::getName, String.CASE_INSENSITIVE_ORDER); to break ties, .thenComparing(Product::getPrice); and if names can be null, wrap with Comparator.nullsFirst. To sort the existing list in place rather than create a new one, use products.sort(Comparator.comparing(Product::getName)).',
    'How would you sort by category, then by price descending?', src),
  Q('nq-061', CX, 'E', 'concept', 'What is the difference between Comparable and Comparator?',
    [kp('Comparable: natural order inside the class, compareTo', 'comparable', 'compareto', 'natural order'), kp('Comparator: external strategy, compare(a,b)', 'comparator', 'compare', 'external'), kp('One natural order vs many comparators', 'many', 'multiple', 'one'), kp('java.lang vs java.util; used by sort, TreeMap', 'java.lang', 'java.util', 'treemap', 'sort')],
    'Comparable lives in java.lang and is implemented by the class itself, class Product implements Comparable<Product>, with compareTo(Product other) defining its single natural ordering; String, Integer and LocalDate implement it. Comparator lives in java.util and is a separate object with compare(a, b), so you can define many orderings without touching the class, such as by price, by name, or by category then price, and even for classes you cannot modify. Sorting methods, TreeSet and TreeMap use the natural order when no comparator is given, or the comparator you pass. Since Java 8 comparators are easy to build with Comparator.comparing.',
    'What contract should compareTo follow with equals?', src),
  Q('nq-062', CX, 'E', 'concept', 'Why might sorted() not work directly for a custom object?',
    [kp('sorted() without arguments uses natural order (Comparable)', 'natural order', 'comparable', 'no argument*'), kp('ClassCastException if the class does not implement Comparable', 'classcastexception', 'exception'), kp('Fix: implement Comparable or pass a Comparator', 'comparator', 'implement')],
    'The no-argument sorted() sorts by natural ordering, which means each element must implement Comparable. A plain Product class does not, so the pipeline compiles but fails at runtime with ClassCastException: Product cannot be cast to Comparable, when the terminal operation runs. The fix is either to make Product implement Comparable<Product> with a sensible compareTo, if there is one obvious natural order, or more commonly to pass a Comparator: sorted(Comparator.comparing(Product::getName)).',
    'Why does this fail at runtime and not at compile time?', src),
  Q('nq-063', CX, 'E', 'concept', 'How would you use Comparator.comparing() to sort objects by a particular field?',
    [kp('Comparator.comparing(keyExtractor) with a method reference', 'comparator.comparing', 'key extractor', 'method reference'), kp('comparingInt/comparingDouble avoid boxing', 'comparingint', 'comparingdouble'), kp('Chain thenComparing and reversed', 'thencomparing', 'reversed'), kp('Optional key comparator as second argument', 'second argument', 'case_insensitive', 'key comparator')],
    'Comparator.comparing takes a key extractor function and builds a comparator that compares those keys by natural order: Comparator.comparing(Product::getPrice). For primitive keys, comparingInt, comparingLong and comparingDouble avoid boxing: Comparator.comparingDouble(Product::getPrice). A second argument supplies a comparator for the key, such as comparing(Product::getName, String.CASE_INSENSITIVE_ORDER). Comparators chain: comparing(Product::getCategory).thenComparing(Product::getPrice, Comparator.reverseOrder()), and reversed() flips the whole order. Pass it to sorted, list.sort, max, min or a TreeMap.',
    'Why can reversed() behave unexpectedly in a chain?', src),
  Q('nq-064', CX, 'E', 'scenario', 'How would you convert product names to uppercase using method references?',
    [kp('map(Product::getName) then map(String::toUpperCase)', 'product::getname', 'string::touppercase', 'map'), kp('Unbound instance method references', 'arbitrary object', 'unbound', 'instance method'), kp('Collect to list; Locale consideration', 'tolist', 'collect', 'locale')],
    'List<String> names = products.stream().map(Product::getName).map(String::toUpperCase).toList(); Both are references to an instance method of an arbitrary object: Product::getName means p -> p.getName(), and String::toUpperCase means s -> s.toUpperCase(). Two simple maps read better than one lambda doing both. For locale safe behaviour, for example Turkish i, use s -> s.toUpperCase(Locale.ROOT). If you need products with upper case names rather than just strings, map to new Product objects instead.',
    'Which of the four method reference kinds is String::toUpperCase?', src),
  Q('nq-065', CX, 'M', 'scenario', 'How would you group products by category using Collectors.groupingBy()?',
    [kp('collect(Collectors.groupingBy(Product::getCategory)) gives Map<String, List<Product>>', 'groupingby', 'map<string, list', 'getcategory'), kp('Downstream collectors: counting, mapping, summingDouble', 'downstream', 'counting', 'mapping', 'summingdouble'), kp('Map factory e.g. TreeMap::new for sorted keys', 'treemap', 'map factory'), kp('partitioningBy for true/false groups', 'partitioningby')],
    'Map<String, List<Product>> byCategory = products.stream().collect(Collectors.groupingBy(Product::getCategory)); The classifier function gives the key, and by default the values are lists of products in a HashMap. A downstream collector changes what is stored per key: groupingBy(Product::getCategory, Collectors.counting()) for counts, mapping(Product::getName, toList()) for names only, or summingDouble for totals. A three argument version takes a map factory, for example TreeMap::new for keys in sorted order. For a two-way split, partitioningBy(p -> p.getStock() < 10) gives a Map<Boolean, List<Product>>.',
    'How would you get the product names per category, sorted?', src),
  Q('nq-066', CX, 'M', 'scenario', 'How would you calculate the total price of products in each category?',
    [kp('groupingBy(category, summingDouble(price))', 'groupingby', 'summingdouble'), kp('Result Map<String, Double>', 'map<string, double>', 'map'), kp('Alternatives: reducing, toMap with merge Double::sum', 'tomap', 'double::sum', 'reducing'), kp('Price times stock if total stock value is meant; BigDecimal for money', 'stock', 'bigdecimal', 'quantity')],
    'Map<String, Double> totals = products.stream().collect(Collectors.groupingBy(Product::getCategory, Collectors.summingDouble(Product::getPrice))); groupingBy groups by category, and the downstream summingDouble adds the prices in each group. An equivalent is Collectors.toMap(Product::getCategory, Product::getPrice, Double::sum), where the merge function adds values on duplicate keys. I would confirm whether the total should be the sum of unit prices or of stock value, price times stock, which would be summingDouble(p -> p.getPrice() * p.getStock()). With BigDecimal prices, use reducing(BigDecimal.ZERO, Product::getPrice, BigDecimal::add).',
    'How would you also get count, min, max and average in one pass?', src),
  Q('nq-067', CX, 'M', 'concept', 'Why might mapToDouble() be unnecessary if getPrice() already returns a double?',
    [kp('Collectors.summingDouble already takes a ToDoubleFunction', 'summingdouble', 'todoublefunction'), kp('Method reference returning primitive double works directly', 'primitive', 'method reference', 'already'), kp('mapToDouble needed only for DoubleStream operations like sum()/average()', 'doublestream', 'sum()', 'average'), kp('No boxing happens when the getter returns double', 'boxing', 'unboxing')],
    'Inside a collector such as Collectors.summingDouble(Product::getPrice) or averagingDouble, the collector already accepts a ToDoubleFunction, and getPrice returning a primitive double fits it directly, so an extra mapToDouble step before collecting is redundant. mapToDouble is useful when you want to stay on a primitive DoubleStream and call its own terminal operations, such as products.stream().mapToDouble(Product::getPrice).sum() or summaryStatistics(). Since getPrice already returns a primitive, there is no boxing to remove either; mapToDouble would only matter if the getter returned a Double object.',
    'Which is clearer to read, and does performance differ?', src),
  Q('nq-068', CX, 'M', 'scenario', 'How would you find the product with the maximum price?',
    [kp('stream().max(Comparator.comparingDouble(Product::getPrice))', 'max', 'comparingdouble', 'comparator'), kp('Returns Optional<Product>; handle empty', 'optional', 'empty', 'orelsethrow'), kp('Collectors.maxBy as an alternative or per group', 'maxby', 'collectors'), kp('Ties: decide which product to return', 'tie*', 'same price', 'share the top price', 'several products')],
    'Optional<Product> mostExpensive = products.stream().max(Comparator.comparingDouble(Product::getPrice)); max takes a comparator and returns an Optional because the list may be empty, so I would handle it with orElseThrow or ifPresent. If I only need the price, products.stream().mapToDouble(Product::getPrice).max() gives an OptionalDouble. Per category it is groupingBy(Product::getCategory, Collectors.maxBy(Comparator.comparingDouble(Product::getPrice))). If several products share the top price, max returns one of them; to get all, find the max price first, then filter by it.',
    'How would you return all products sharing the highest price?', src),
  Q('nq-069', CX, 'E', 'concept', 'What does Comparator.comparingDouble() return?',
    [kp('Returns a Comparator<T>', 'comparator<t>', 'comparator'), kp('Compares by a double key extracted with ToDoubleFunction', 'todoublefunction', 'double key', 'key extractor'), kp('Uses Double.compare, no boxing', 'double.compare', 'boxing')],
    'It returns a Comparator<T>. You give it a ToDoubleFunction that extracts a primitive double key from each object, such as Product::getPrice, and the returned comparator compares two objects by calling Double.compare on their keys, which avoids boxing and handles special values such as NaN and minus zero consistently. You can pass it to sorted, max, min or sort, and chain it with reversed or thenComparing.',
    'Why is Double.compare used instead of subtracting prices?', src),
  Q('nq-070', CX, 'E', 'concept', 'Why does the max() stream operation return an Optional?',
    [kp('Stream may be empty, so there may be no maximum', 'empty', 'no maximum', 'no element*'), kp('Avoids returning null or throwing', 'null', 'throw*'), kp('Caller decides: orElse, orElseThrow, ifPresent', 'orelse', 'orelsethrow', 'ifpresent')],
    'Because the stream might have no elements, and then there is no maximum to return. Instead of returning null, which invites a NullPointerException, or throwing an exception, the API returns Optional<T>, empty for an empty stream. The caller then decides explicitly what an empty input means: a default with orElse, an error with orElseThrow, or an action with ifPresent. The same applies to min, findFirst, findAny and reduce without an identity.',
    'Which reduce overload does not return an Optional, and why?', src),
  Q('nq-071', CX, 'M', 'scenario', 'What alternative approaches can you use to find the maximum price without stream max()?',
    [kp('Classic for loop tracking the max', 'loop', 'for', 'track*'), kp('Collections.max with a comparator', 'collections.max'), kp('mapToDouble().max() / summaryStatistics()', 'summarystatistics', 'mapToDouble', 'doublestream'), kp('reduce or sort then take last (less efficient)', 'reduce', 'sort*', 'last'), kp('Complexity O(n) vs O(n log n) for sorting', 'o(n)', 'n log n')],
    'A plain loop is simplest and O(n): start with the first product, or negative infinity for the price, and update whenever a higher price is found, handling an empty list. Collections.max(products, Comparator.comparingDouble(Product::getPrice)) does the same and throws NoSuchElementException on an empty list. With streams but without max, products.stream().mapToDouble(Product::getPrice).summaryStatistics().getMax() also gives min, average and count in one pass, or reduce((a, b) -> a.getPrice() >= b.getPrice() ? a : b). Sorting the list and taking the last element works but costs O(n log n), so it is the least efficient.',
    'Which approach would you use in production code, and why?', src),
  Q('nq-072', CX, 'SL', 'scenario', 'How would you optimize a stream pipeline that performs multiple operations?',
    [kp('Filter early to reduce elements before expensive maps', 'filter early', 'filter first', 'order of operation*', 'before', 'filter steps first', 'selective'), kp('Avoid multiple passes; compute several aggregates in one collector (teeing, summaryStatistics)', 'one pass', 'single pass', 'teeing', 'summarystatistics'), kp('Primitive streams to avoid boxing', 'primitive', 'boxing', 'mapToDouble'), kp('Short-circuit operations, avoid unnecessary sorted/distinct', 'short circuit*', 'sorted', 'distinct', 'findfirst'), kp('Measure before optimising; parallel only when justified', 'measure', 'profile', 'jmh', 'parallel')],
    'First measure, since streams over a few hundred items are rarely a bottleneck. Then: put cheap, selective filter steps first so expensive maps and sorting see fewer elements; avoid sorted or distinct unless needed, since they are stateful and buffer everything; use short-circuiting terminals like anyMatch or findFirst instead of collecting and checking; use primitive streams such as mapToDouble to avoid boxing; and avoid streaming the same list many times when one pass can produce several results, using a combined collector like Collectors.teeing, summaryStatistics, or groupingBy with a downstream collector. Avoid side effects and debug peek calls in hot code. Consider a parallel stream only for large, CPU heavy work.',
    'How does Collectors.teeing help here?', src),
  Q('nq-073', CX, 'SL', 'scenario', 'Which product-processing operations are suitable for parallel execution?',
    [kp('Independent per-element CPU work on large lists: price calculation, mapping, filtering', 'independent', 'cpu', 'large', 'calculation'), kp('Associative aggregations: sum, count, max, groupingBy (concurrent)', 'sum', 'count', 'max', 'associative', 'groupingbyconcurrent'), kp('Not suitable: ordered output, shared mutable updates, I/O or DB calls', 'order*', 'shared', 'database', 'i/o', 'mutat*'), kp('Small lists: overhead outweighs benefit', 'small', 'overhead')],
    'Good candidates are operations where each product is processed independently and the work is CPU bound on a large collection, say hundreds of thousands of products: computing discounted or taxed prices into new objects, filtering by computed rules, and associative aggregations such as total price, counts, min or max, or grouping by category with groupingByConcurrent. Poor candidates: anything that needs results in a strict order with forEachOrdered or sorted, updating shared mutable objects or an external list, operations that call a database or remote service per product, which block the common pool, and small lists where the overhead dominates. Always benchmark before choosing parallel.',
    'Why is calling a pricing REST API from a parallel stream a bad idea?', src),

  // ---------------------------------------------------------------- 5. Multithreading and concurrency
  Q('nq-074', CC, 'E', 'concept', 'What are the different ways to create threads in Java?',
    [kp('Extend Thread and override run', 'extend* thread', 'override run', 'extends thread'), kp('Implement Runnable (or lambda) and pass to Thread', 'runnable', 'lambda'), kp('Callable with ExecutorService returning Future', 'callable', 'executorservice', 'future'), kp('CompletableFuture async, virtual threads (Thread.ofVirtual)', 'completablefuture', 'virtual thread*', 'thread.ofvirtual'), kp('start() not run()', 'start', 'run()')],
    'There are several ways. Extend Thread and override run, then call start. Implement Runnable, usually as a lambda, and pass it to new Thread(runnable).start(), which separates the task from the thread. Implement Callable when the task returns a value or throws a checked exception, and submit it to an ExecutorService, which gives back a Future; in real applications thread pools from Executors or Spring are preferred over creating threads manually. CompletableFuture.supplyAsync runs tasks on a pool asynchronously, and since Java 21 Thread.ofVirtual().start() or a virtual thread per task executor creates virtual threads. Always call start, not run, which would execute on the current thread.',
    'What happens if you call run() instead of start()?', src),
  Q('nq-075', CC, 'E', 'concept', 'What is the difference between extending Thread and implementing Runnable?',
    [kp('Java single inheritance: extending Thread uses up the superclass', 'single inheritance', 'cannot extend', 'superclass'), kp('Runnable separates task from execution mechanism', 'separat*', 'task', 'decoupl*'), kp('Runnable can be submitted to executors / reused', 'executor*', 'thread pool', 'reuse'), kp('Prefer Runnable (composition over inheritance)', 'prefer', 'composition')],
    'Extending Thread ties your task to the thread mechanism and uses your only superclass, since Java has single inheritance, so the class cannot extend anything else. Implementing Runnable keeps the task separate from how it is executed: the same Runnable can run in a new Thread, in an ExecutorService thread pool, in a scheduled executor or a virtual thread, and the class remains free to extend another class. It also follows composition over inheritance and you only need to override behaviour, not the whole thread. So Runnable, or a lambda, is the preferred approach; you extend Thread only to customise thread behaviour itself.',
    'Is Thread itself a Runnable?', src),
  Q('nq-076', CC, 'E', 'concept', 'What is the difference between Runnable and Callable?',
    [kp('Runnable.run returns void; Callable.call returns a value', 'void', 'return* a value', 'call()', 'run()'), kp('Callable can throw checked exceptions', 'checked exception*', 'throws exception'), kp('Callable used with ExecutorService.submit returning Future', 'future', 'submit', 'executorservice'), kp('Runnable usable with Thread directly', 'new thread', 'thread directly', 'straight to a thread')],
    'Runnable has void run(): it cannot return a result and cannot throw checked exceptions. Callable<V> has V call() throws Exception: it returns a value and can throw checked exceptions. You can pass a Runnable straight to a Thread, while a Callable is submitted to an ExecutorService, which returns a Future<V>; future.get() waits for the result and wraps any exception thrown by call in an ExecutionException. ExecutorService.submit also accepts Runnable, in which case the Future result is null. Use Callable for tasks that compute something, like fetching a price, and Runnable for fire-and-forget work.',
    'How do you get the exception thrown inside a Callable?', src),
  Q('nq-077', CC, 'E', 'concept', 'What is ExecutorService, and why is it used?',
    [kp('Framework that manages a pool of worker threads', 'thread pool', 'pool', 'manage*'), kp('Reuses threads, avoiding creation cost and controlling concurrency', 'reuse', 'creation', 'control'), kp('submit/invokeAll return Futures; task queue', 'submit', 'future*', 'invokeall', 'queue'), kp('Factory methods: fixed, cached, scheduled, virtual-thread-per-task', 'newfixedthreadpool', 'cached', 'scheduled', 'virtual'), kp('Must shutdown / awaitTermination', 'shutdown', 'awaittermination', 'close')],
    'ExecutorService, in java.util.concurrent, decouples submitting tasks from running them. It manages a pool of worker threads and a task queue: you submit Runnable or Callable tasks and get Futures back, while the executor reuses threads instead of creating one per task, which saves creation cost and limits how many run at once so a burst of work does not exhaust memory or CPU. Executors provides factories such as newFixedThreadPool, newCachedThreadPool, newScheduledThreadPool, newWorkStealingPool and newVirtualThreadPerTaskExecutor, or you build a ThreadPoolExecutor with explicit queue size and rejection policy. Always shut it down, with shutdown and awaitTermination or try-with-resources.',
    'Why is an unbounded queue in a fixed thread pool risky?', src),
  Q('nq-078', CC, 'M', 'concept', 'How do threads communicate with one another in Java?',
    [kp('Shared memory protected by synchronization', 'shared memory', 'shared', 'synchroni*'), kp('wait/notify/notifyAll on a monitor; Condition await/signal', 'wait', 'notify', 'condition', 'signal'), kp('BlockingQueue producer-consumer', 'blockingqueue', 'producer', 'consumer'), kp('Futures/CompletableFuture, CountDownLatch, Exchanger', 'future', 'completablefuture', 'countdownlatch', 'exchanger'), kp('volatile flags for visibility', 'volatile', 'visib*')],
    'Threads in one JVM communicate through shared memory, so the question is how to do it safely. The low level way is a shared object guarded by synchronized, with wait, notify and notifyAll for one thread to wait until another changes a condition, or Lock with Condition await and signal. Better, use higher level tools: a BlockingQueue for producer consumer hand off, where put blocks when full and take blocks when empty; Future and CompletableFuture to pass a result; CountDownLatch, CyclicBarrier, Semaphore and Exchanger for coordination; and a volatile boolean for a simple stop flag. These handle visibility and ordering correctly.',
    'Why should wait() always be called in a loop?', src),
  Q('nq-079', CC, 'E', 'concept', 'What is thread safety?',
    [kp('Correct behaviour when accessed by multiple threads concurrently', 'multiple thread*', 'concurren*', 'correct'), kp('No race conditions, visibility problems or corrupted state', 'race condition*', 'visibility', 'corrupt*', 'inconsistent'), kp('Achieved via immutability, confinement, synchronization, atomics, concurrent collections', 'immutab*', 'synchroni*', 'atomic*', 'concurrent collection*', 'lock*'), kp('Examples: StringBuilder vs StringBuffer, HashMap vs ConcurrentHashMap', 'stringbuffer', 'concurrenthashmap', 'hashmap')],
    'Code is thread safe when it behaves correctly no matter how threads are scheduled, with no extra coordination by callers: invariants hold, no updates are lost, and every thread sees up-to-date values. Problems come from shared mutable state: race conditions such as count++ losing updates, visibility issues where one thread never sees another thread write, and broken invariants. You achieve thread safety by not sharing (thread confinement, local variables), by not mutating (immutable objects), or by coordinating: synchronized, locks, atomic classes and concurrent collections such as ConcurrentHashMap. For example HashMap and StringBuilder are not thread safe, while ConcurrentHashMap is.',
    'Is an immutable object automatically thread safe?', src),
  Q('nq-080', CC, 'E', 'concept', 'What is a race condition, and how can it occur?',
    [kp('Result depends on the timing/interleaving of threads', 'timing', 'interleav*', 'order of execution'), kp('Read-modify-write like count++ is not atomic', 'count++', 'read modify write', 'not atomic'), kp('Check-then-act races (if absent then put)', 'check then act', 'check-then-act', 'if absent'), kp('Fix: synchronization, atomics, locks', 'synchroni*', 'atomic*', 'lock*')],
    'A race condition happens when the correctness of a result depends on the unpredictable interleaving of threads accessing shared data. The classic example is count++: it is really read, add one, write back, so two threads can both read 5 and both write 6, losing an update. Another is check then act: if (!map.containsKey(k)) map.put(k, v) where two threads both see the key missing. Bank balance updates and lazy singleton creation have the same problem. You fix it by making the compound action atomic, with synchronized, a Lock, AtomicInteger.incrementAndGet, or atomic methods like ConcurrentHashMap.putIfAbsent and computeIfAbsent.',
    'How would you reproduce a race condition in a test?', src),
  Q('nq-081', CC, 'M', 'concept', 'What is dirty writing, and how can concurrent access cause inconsistent results?',
    [kp('One writer overwrites another uncommitted/in-progress change', 'overwrite*', 'uncommitted', 'lost update*'), kp('Concurrent read-modify-write without coordination', 'concurrent', 'read modify write', 'without lock*', 'without synchronisation', 'two threads'), kp('Results: lost updates, inconsistent totals', 'lost update*', 'inconsistent'), kp('Prevent with locks, synchronization, optimistic locking/versioning or transactions', 'lock*', 'optimistic', 'version', 'transaction*', 'isolation')],
    'A dirty write is when one thread or transaction overwrites data that another has written but not yet finished or committed, so one change silently wins and the other is lost or the data ends up as a mix of both. In Java, two threads updating the fields of the same account object without synchronisation can leave the balance from one thread and the timestamp from another. In databases, two transactions updating the same row without proper isolation cause lost updates. The cure is coordination: synchronized or locks around compound updates in memory, and in databases row locks, transaction isolation, or optimistic locking with a version column, as JPA @Version does.',
    'How does JPA optimistic locking detect a conflicting write?', src),
  Q('nq-082', CC, 'M', 'concept', 'What is the purpose of the volatile keyword?',
    [kp('Guarantees visibility of writes to all threads (no caching in registers/CPU cache)', 'visib*', 'main memory', 'cache'), kp('Prevents reordering (happens-before)', 'reorder*', 'happens before', 'happens-before'), kp('Does not make compound operations atomic (count++)', 'not atomic', 'count++', 'compound'), kp('Use for flags and double-checked locking', 'flag*', 'double checked', 'stop')],
    'volatile guarantees visibility and ordering for a field. Without it, a thread may keep reading a cached value and never see another thread update, for example a while (!stopped) loop that never ends. A write to a volatile variable happens-before every later read of it, so readers always see the latest value and also everything the writer did before the write; the JVM and CPU are not allowed to reorder across it. But volatile does not provide atomicity: count++ on a volatile int still loses updates. Use it for simple flags, status fields written by one thread, and the instance field in double-checked locking.',
    'Why is volatile needed in double-checked locking?', src),
  Q('nq-083', CC, 'M', 'concept', 'How does volatile differ from synchronization?',
    [kp('volatile: visibility only; synchronized: visibility and mutual exclusion/atomicity', 'mutual exclusion', 'atomic*', 'visibility'), kp('volatile on fields; synchronized on methods/blocks', 'field*', 'method*', 'block*'), kp('volatile never blocks; synchronized acquires a monitor lock', 'block*', 'monitor', 'lock'), kp('Use volatile for single-writer flags, synchronized for compound actions', 'flag*', 'compound', 'single writer')],
    'volatile only guarantees that reads and writes of that one variable are visible to all threads and not reordered; it never blocks and gives no atomicity for compound actions. synchronized guarantees mutual exclusion, so only one thread at a time runs the guarded code on the same monitor, and also visibility, because releasing a monitor publishes changes and acquiring it sees them. So a volatile boolean is fine as a stop flag, but incrementing a shared counter or updating two related fields together needs synchronized, a Lock, or atomic classes. volatile is cheaper; synchronized is broader.',
    'Can you make count++ safe with volatile alone?', src),
  Q('nq-084', CC, 'E', 'concept', 'What is the difference between synchronized and unsynchronized resources?',
    [kp('Synchronized: only one thread at a time accesses the resource', 'one thread at a time', 'mutual exclusion', 'lock'), kp('Unsynchronized: concurrent access, faster but unsafe for shared mutation', 'unsafe', 'faster', 'concurrent'), kp('Examples Vector/StringBuffer vs ArrayList/StringBuilder', 'vector', 'stringbuffer', 'stringbuilder', 'arraylist'), kp('Choose synchronized only when shared; cost of contention', 'contention', 'overhead', 'shared')],
    'A synchronized resource controls access so that only one thread at a time can execute its critical methods, for example Vector, Hashtable or StringBuffer, whose methods are synchronized. That makes single operations thread safe but adds locking overhead and contention. Unsynchronized resources such as ArrayList, HashMap and StringBuilder allow any thread in at any time; they are faster and right for data used by one thread, but corrupt or lose data when several threads modify them. Modern code uses unsynchronized classes for local data and concurrent collections, like ConcurrentHashMap, for shared data, rather than the old fully synchronized classes.',
    'Why are Vector and Hashtable considered legacy?', src),
  Q('nq-085', CC, 'M', 'concept', 'What is the difference between wait(), sleep(), yield(), and join()?',
    [kp('wait(): Object method, releases the monitor, waits for notify, must hold lock', 'wait', 'releases', 'notify', 'monitor'), kp('sleep(): Thread static, pauses for time, keeps locks', 'sleep', 'keeps', 'does not release'), kp('yield(): hint to scheduler to let others run', 'yield', 'hint', 'scheduler'), kp('join(): waits for another thread to finish', 'join', 'finish', 'complete')],
    'wait is an Object method called inside a synchronized block on that object: the thread releases the monitor and waits until another thread calls notify or notifyAll, or a timeout, then reacquires the lock. sleep is a static Thread method that pauses the current thread for a given time without releasing any locks it holds. yield is a static hint to the scheduler that the current thread is willing to give up the CPU so others may run; it is rarely useful and has no guarantees. join is called on another thread object and makes the current thread wait until that thread terminates, optionally with a timeout. wait, sleep and join throw InterruptedException.',
    'What happens if you call wait() without holding the lock?', { ...src, sameAs: 'java-220' }),
  Q('nq-086', CC, 'M', 'concept', 'What is CountDownLatch, and how does it work with multiple threads?',
    [kp('Synchroniser initialised with a count', 'count', 'initiali*'), kp('Workers call countDown(); waiting thread calls await()', 'countdown', 'await'), kp('await returns when count reaches zero', 'zero'), kp('One-time use, cannot be reset (vs CyclicBarrier)', 'one time', 'reset', 'cyclicbarrier'), kp('Use case: wait for N services/tasks to start or finish', 'wait for', 'tasks', 'services', 'start*')],
    'CountDownLatch is a java.util.concurrent synchroniser created with a count, for example new CountDownLatch(3). Each worker thread calls countDown when it finishes its part, and one or more threads call await, which blocks until the count reaches zero, then all waiting threads proceed. A typical use is a main thread waiting until three services are initialised, or tests starting many threads at the same moment with a latch of one. It is one-shot: once it reaches zero it stays open and cannot be reset; for repeated rounds use CyclicBarrier or Phaser. Always call countDown in a finally block so a failing worker does not leave others waiting forever.',
    'How is CyclicBarrier different from CountDownLatch?', src),
  Q('nq-087', CC, 'M', 'scenario', 'How can you wait for multiple concurrent tasks to complete?',
    [kp('ExecutorService.invokeAll or collect Futures and get()', 'invokeall', 'future', 'get()'), kp('CompletableFuture.allOf(...).join()', 'allof', 'completablefuture'), kp('CountDownLatch / join on threads', 'countdownlatch', 'join'), kp('Timeouts and failure handling', 'timeout', 'exception', 'failure'), kp('Structured concurrency / try-with-resources executor (Java 21)', 'structured concurrency', 'structuredtaskscope', 'try with resources')],
    'Options from low to high level: call join on each Thread; use a CountDownLatch counted down by each task; submit Callables to an ExecutorService and call get on each Future, or use invokeAll, which returns when all finish; or with CompletableFuture, CompletableFuture.allOf(f1, f2, f3).join() and then read each result. Since Java 19 an ExecutorService in try-with-resources waits for its tasks on close, and Java 21 structured concurrency, StructuredTaskScope, makes a group of subtasks complete or fail together. Always add timeouts, for example get(5, SECONDS) or orTimeout, and decide whether one failure should cancel the rest.',
    'How would you fail fast if one of the tasks throws?', src),
  Q('nq-088', CC, 'M', 'concept', 'What is CompletableFuture, and how does it support asynchronous programming?',
    [kp('Future that can be completed and composed (CompletionStage)', 'completionstage', 'compose*', 'complet*'), kp('supplyAsync/runAsync run tasks on a pool', 'supplyasync', 'runasync'), kp('Non-blocking callbacks: thenApply, thenCompose, thenCombine, thenAccept', 'thenapply', 'thencompose', 'thencombine', 'thenaccept', 'callback*'), kp('Exception handling: exceptionally, handle, whenComplete', 'exceptionally', 'handle', 'whencomplete'), kp('allOf/anyOf, timeouts', 'allof', 'anyof', 'ortimeout')],
    'CompletableFuture, from Java 8, is a Future that you can complete manually and, more importantly, compose. supplyAsync and runAsync start work on the common ForkJoinPool or an executor you pass. Instead of blocking with get, you attach callbacks that run when the result is ready: thenApply to transform, thenAccept to consume, thenCompose to chain another async call, thenCombine to merge two independent results, and allOf or anyOf to coordinate many. Errors flow down the chain and are handled with exceptionally, handle or whenComplete. Java 9 added orTimeout and completeOnTimeout. This lets you call several services in parallel and combine results without blocking threads.',
    'Why should you pass your own executor for I/O tasks?', src),
  Q('nq-089', CC, 'M', 'concept', 'How does CompletableFuture differ from Future and Callable?',
    [kp('Callable is the task; Future is a handle to its result', 'task', 'handle', 'result'), kp('Future: only blocking get(), isDone, cancel; no chaining', 'blocking', 'get()', 'no chain*', 'cannot chain'), kp('CompletableFuture: callbacks, composition, combining, manual completion', 'callback*', 'compos*', 'combin*', 'complete()'), kp('Built-in exception handling', 'exceptionally', 'exception')],
    'Callable is just a task that returns a value. Future is the handle you get when you submit it to an executor, and it is limited: you can check isDone, cancel, or block with get to wait for the result, but you cannot attach a callback, chain another step, combine two futures, or handle an exception without blocking. CompletableFuture implements both Future and CompletionStage: you can still block with get or join, but you mostly build non-blocking pipelines with thenApply, thenCompose, thenCombine and allOf, handle errors with exceptionally or handle, and you can complete it yourself with complete or completeExceptionally, which is useful for bridging callback APIs.',
    'When might a plain Future still be enough?', src),
  Q('nq-090', CC, 'M', 'concept', 'How does CompletableFuture handle return values, exceptions, and chained tasks?',
    [kp('Return values passed along the chain: thenApply/thenCompose', 'thenapply', 'thencompose', 'pass*'), kp('Exception skips subsequent stages until handled', 'skip*', 'propagat*', 'completed exceptionally'), kp('exceptionally / handle / whenComplete to recover or log', 'exceptionally', 'handle', 'whencomplete'), kp('join/get wrap exceptions in CompletionException/ExecutionException', 'completionexception', 'executionexception')],
    'Each stage receives the previous stage result: thenApply transforms it synchronously, thenCompose flattens a function that returns another CompletableFuture, thenCombine merges two results, and thenAccept consumes it. If any stage throws, the future completes exceptionally and the following dependent stages are skipped, the exception propagating down the chain. You recover with exceptionally(ex -> fallback), which runs only on failure; handle((value, ex) -> ...), which always runs and can map either outcome; or observe with whenComplete without changing the result. Calling join throws an unchecked CompletionException wrapping the cause, while get throws a checked ExecutionException.',
    'Where should exceptionally be placed in a long chain?', src),
  Q('nq-091', CC, 'M', 'concept', 'What is the purpose of thenApply() and thenApplyAsync()?',
    [kp('Both transform the result with a Function, returning a new CompletableFuture', 'transform*', 'function', 'new completablefuture'), kp('thenApply runs in the thread that completed the previous stage (or caller)', 'same thread', 'completing thread', 'caller', 'thread that completed'), kp('thenApplyAsync runs on another thread: common pool or given executor', 'async', 'another thread', 'executor', 'common pool'), kp('Use async variant for heavy work or to avoid blocking the completing thread', 'heavy', 'blocking', 'avoid')],
    'Both apply a Function to the result of the previous stage and return a new CompletableFuture with the transformed value. thenApply runs the function synchronously: in the thread that completed the previous stage, or in the calling thread if the future is already complete. thenApplyAsync submits the function as a new task to the default async executor, the common ForkJoinPool, or to an executor you pass as the second argument. Use thenApply for cheap transformations such as mapping a DTO. Use thenApplyAsync, with your own executor, when the transformation is heavy or blocking, or when you must not run it on the thread that completed the stage, such as an I/O event loop.',
    'What is the downside of making every stage async?', src),
  Q('nq-092', CC, 'M', 'concept', 'What is the difference between ReentrantLock and synchronized?',
    [kp('Both provide mutual exclusion and are reentrant', 'mutual exclusion', 'reentrant'), kp('ReentrantLock: tryLock, timeouts, interruptible locking', 'trylock', 'timeout', 'interruptib*', 'lockinterruptibly'), kp('Fairness option and multiple Conditions', 'fair*', 'condition*'), kp('Must unlock in finally; synchronized releases automatically', 'finally', 'unlock', 'automatic*'), kp('Does not pin virtual threads (pre Java 24)', 'virtual thread*', 'pin*')],
    'Both give mutual exclusion and memory visibility, and both are reentrant, so a thread holding the lock can enter again. synchronized is a language keyword: simple, the lock is released automatically even on exceptions, and the JVM optimises it well. ReentrantLock is a class that offers more control: tryLock to attempt without blocking or with a timeout, lockInterruptibly so a waiting thread can be interrupted, an optional fairness policy, several Condition objects for different wait sets, and methods to inspect the lock. The cost is that you must call unlock in a finally block yourself. Before Java 24 it also avoided pinning virtual threads, unlike synchronized.',
    'When does tryLock help avoid deadlocks?', src),
  Q('nq-093', CC, 'M', 'concept', 'What is a ReadWriteLock, and how does it differ from ReentrantLock?',
    [kp('Separate read lock (shared) and write lock (exclusive)', 'read lock', 'write lock', 'shared', 'exclusive'), kp('Many readers concurrently when no writer', 'many readers', 'multiple readers', 'concurrent read*', 'many threads can hold'), kp('Best for read-heavy data such as caches', 'read heavy', 'read-heavy', 'cache'), kp('ReentrantLock is always exclusive; StampedLock optimistic reads', 'exclusive', 'stampedlock', 'optimistic')],
    'A ReadWriteLock, such as ReentrantReadWriteLock, holds a pair of locks: a read lock that many threads can hold at the same time as long as no thread holds the write lock, and a write lock that is exclusive, blocking all readers and writers. A ReentrantLock is always exclusive, so even two readers would wait for each other. Read write locks pay off for data that is read often and written rarely, like an in-memory configuration or cache, where readers can run in parallel. They have more overhead and can starve writers under heavy reading; StampedLock adds optimistic reads for even cheaper read paths.',
    'Can you upgrade a read lock to a write lock?', src),
  Q('nq-094', CC, 'MS', 'scenario', 'When would you use explicit locks instead of synchronized blocks?',
    [kp('Need tryLock or timeouts to avoid deadlock/wait forever', 'trylock', 'timeout', 'deadlock'), kp('Interruptible lock acquisition', 'interrupt*', 'lockinterruptibly'), kp('Fairness or multiple conditions', 'fair*', 'condition*'), kp('Read-write separation; lock across methods', 'read write', 'readwritelock', 'across method*', 'hand over hand'), kp('Virtual threads pinning with long synchronized sections', 'virtual thread*', 'pin*')],
    'I stay with synchronized for simple critical sections because it is shorter and cannot forget to unlock. I switch to explicit locks when I need features it lacks: tryLock with a timeout so a thread can give up instead of waiting forever or deadlocking, for example when locking two accounts; lockInterruptibly so a cancelled task can stop waiting; a fair lock so long-waiting threads go first; several Condition queues, such as notFull and notEmpty in a bounded buffer; read write separation for read-heavy data; or acquiring and releasing in different methods. On Java 21 to 23 with virtual threads, ReentrantLock also avoids pinning around blocking calls.',
    'Can you show how tryLock can prevent a deadlock in a money transfer?', src),
];
